                    while ((read = proc.StandardOutput.BaseStream.Read(buf, 0, buf.Length)) > 0) {{
                        stream.Write(buf, 0, read);
                        stream.Flush();
                    }}
                }});
                writeThread.Start();
                readThread.Join();
                writeThread.Join();
                proc.WaitForExit();
            }}
        }}
    }}
}}
